# -*- coding: utf-8 -*-
# RE_PATH (triage record, generated by local_writer v2):
#   framework : MacCMS v10 dynamic routes (base path (root))
#   list      : (root)/index.php/vod/type/id/{tid}/page/{pg}.html
#   card      : muban1b template
#   play      : (root)/index.php/vod/play/id/... embeds player_aaaa
#   stream    : HLS m3u8 (AES-128 where declared); compliant players handle it natively
#   search    : working route /index.php/vod/search.html?wd={q}
# RE_OBSTACLE:
#   - TLS certificate hostname mismatch on mirror subdomains -> skip verification
#   - mirror subdomains rotate: wildcard DNS on the registrable domain -> host fallback
#   - datacenter IPs may be served decoy content -> verify through residential egress
#   - some front-ends wrap every response in a JSON string -> unwrap before parsing

import re
import json
import gzip
import ssl
import threading
import urllib.parse
import urllib.request

try:
    from base.spider import Spider as _BaseSpider
except Exception:
    class _BaseSpider:
        def __init__(self):
            pass

try:
    _SSL_CTX = ssl._create_unverified_context()
except Exception:
    _SSL_CTX = None

NAME = "十万部毛片✔️"
HOSTS = ["w_vz_m3_4h_y.sesedui2.cfd", "www.sesedui2.cfd", "m.sesedui2.cfd", "a.sesedui2.cfd", "b.sesedui2.cfd"]
BASE = ""
PLAYER_MODE = "json"

UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")

RE_CARD = re.compile("href=\"(/index\\.php/vod/detail/id/\\d+\\.html)\"[^>]*><img class=\"loadi\"[^>]*?data-original=\"([^\"]+)\".*?<h5><a href=\"\\1\"[^>]*>([^<]+)</a>", re.S)
RE_NAV = re.compile("href=\"(/index\\.php/vod/type/id/(\\d+)\\.html)\"[^>]*>\\s*([^<]{1,12}?)\\s*</a>")
RE_PLAYER = re.compile("player_aaaa\\s*=\\s*(\\{.*?\\})\\s*</script>", re.S)
RE_TITLE = re.compile(r'<h1[^>]*>([^<]+)</h1>')

RE_PAGECOUNT = re.compile(r'(\d+)\s*/\s*(\d+)')


def _clean(s):
    return re.sub(r"\s+", " ", (s or "")).strip()


def _unwrap(body):
    """Undo the JSON-string response wrapper used by some mirror front-ends."""
    if not body:
        return body
    s = body.lstrip()
    if len(s) < 2 or s[0] != '"' or s.rstrip()[-1] != '"':
        return body
    try:
        inner = json.loads(s)
    except Exception:
        return body
    return inner if isinstance(inner, str) else body


class Spider(_BaseSpider):
    def __init__(self):
        self.ext = {}
        self._cache = {}
        self._lock = threading.RLock()
        self._host = HOSTS[0]

    def getDependence(self):
        return ""

    def getName(self):
        return NAME

    def init(self, extend=""):
        try:
            if isinstance(extend, dict):
                self.ext = extend
            elif extend:
                self.ext = json.loads(extend)
        except Exception:
            self.ext = {}
        return ""

    def getCategory(self):
        return ""

    def getFilter(self):
        return {}

    def action(self, action):
        return ""

    def destroy(self):
        with self._lock:
            self._cache.clear()
        return ""

    def localProxy(self, param):
        return [404, "text/plain", ""]

    def isVideoFormat(self, url):
        text = str(url or "").lower()
        return bool(re.search(r"\.(?:m3u8|mp4|mkv|flv|avi|ts)(?:[?#]|$)", text))

    def _fetch(self, url, referer=""):
        headers = {
            "User-Agent": UA,
            "Accept": "text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9",
            "Accept-Encoding": "gzip",
            "Connection": "close",
        }
        if referer:
            headers["Referer"] = referer
        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=25, context=_SSL_CTX) as r:
                raw = r.read()
                if raw[:2] == b"\x1f\x8b":
                    try:
                        raw = gzip.decompress(raw)
                    except Exception:
                        pass
                return _unwrap(raw.decode("utf-8", "ignore"))
        except Exception:
            return ""

    def _get(self, path, referer=""):
        if path.startswith("http"):
            url = path
        else:
            url = "https://" + self._host + (path if path.startswith("/") else "/" + path)
        with self._lock:
            cached = self._cache.get(url)
        if cached is not None:
            return cached
        body = self._fetch(url, referer)
        if not body and not path.startswith("http"):
            for host in HOSTS:
                if host == self._host:
                    continue
                alt = "https://" + host + (path if path.startswith("/") else "/" + path)
                body = self._fetch(alt, referer)
                if body:
                    self._host = host
                    url = alt
                    break
        with self._lock:
            self._cache[url] = body
        return body

    def _play_path(self, link):
        """Classic templates link the DETAIL page; MacCMS always exposes the
        matching play page at /vod/play/id/{id}/sid/1/nid/1.html."""
        m = re.search(r'/vod/detail/id/(\d+)\.html', link)
        if m:
            return re.sub(r'/vod/detail/id/\d+\.html$',
                          '/vod/play/id/%s/sid/1/nid/1.html' % m.group(1), link)
        return link

    def _cards(self, body):
        out = []
        seen = set()
        for m in RE_CARD.finditer(body or ""):
            vid = self._play_path(m.group(1).strip())
            if vid in seen:
                continue
            seen.add(vid)
            out.append({
                "vod_id": "https://" + self._host + vid,
                "vod_name": _clean(m.group(3)) or "未知",
                "vod_pic": m.group(2) or "",
                "vod_remarks": "",
            })
        return out

    def _classes(self, body):
        out = []
        seen = set()
        for m in RE_NAV.finditer(body or ""):
            if m.group(2) in seen:
                continue
            seen.add(m.group(2))
            out.append({"type_id": m.group(2), "type_name": _clean(m.group(3))})
        if not out:
            out = [{"type_id": "1", "type_name": "最新"}]
        return out

    def _pagecount(self, body, default=999):
        m = RE_PAGECOUNT.search(body or "")
        if m:
            try:
                return max(1, int(m.group(2)))
            except Exception:
                return default
        return default

    def _stream_url(self, body):
        m = RE_PLAYER.search(body or "")
        if not m:
            return "", None
        if PLAYER_MODE == "url":
            return (m.group(1) or "").strip(), None
        try:
            pd = json.loads(m.group(1))
        except Exception:
            return "", None
        return (pd.get("url") or "").strip(), pd

    def _page_title(self, body, pd=None):
        if pd:
            name = (pd.get("vod_data") or {}).get("vod_name")
            if name:
                return _clean(name)
        m = RE_TITLE.search(body or "")
        return _clean(m.group(1)) if m else ""

    def homeContent(self, *args):
        body = self._get(BASE + "/")
        return {
            "class": self._classes(body),
            "list": self._cards(body),
            "page": 1,
            "pagecount": self._pagecount(body),
            "limit": 20,
            "total": 99999,
        }

    def categoryContent(self, tid, pg, filter, extend, *args):
        try:
            pg = int(pg)
        except Exception:
            pg = 1
        if pg < 1:
            pg = 1
        body = self._get(BASE + "/index.php/vod/type/id/%s/page/%d.html" % (tid, pg))
        vods = self._cards(body)
        return {"list": vods, "page": pg, "pagecount": self._pagecount(body),
                "limit": len(vods), "total": 99999}

    def detailContent(self, ids, *args):
        out = []
        for vid in ids:
            page = str(vid)
            if not page.startswith("http"):
                page = "https://" + self._host + (page if page.startswith("/") else "/" + page)
            body = self._get(page, referer=page)
            m3u8, pd = self._stream_url(body)
            if not m3u8:
                continue
            out.append({
                "vod_id": page,
                "vod_name": self._page_title(body, pd) or "未知",
                "vod_pic": "",
                "vod_play_from": "naixx",
                "vod_play_url": "第1集$%s" % m3u8,
                "vod_remarks": "",
            })
        return {"list": out, "page": 1, "pagecount": 1,
                "limit": len(out), "total": len(out)}

    def playerContent(self, flag, id, vipFlags, *args):
        purl = str(id)
        if purl.endswith(".m3u8"):
            return {"parse": 0, "url": purl,
                    "header": {"Referer": "https://" + self._host + BASE + "/"}}
        if not purl.startswith("http"):
            purl = "https://" + self._host + (purl if purl.startswith("/") else "/" + purl)
        body = self._get(purl, referer=purl)
        url, _pd = self._stream_url(body)
        if not url:
            return {"parse": 0, "url": "", "msg": "stream url not found"}
        return {"parse": 0, "url": url,
                "header": {"Referer": "https://" + self._host + BASE + "/"}}

    def searchContent(self, key, quick=False, pg=1, *args):
        try:
            pg = int(pg)
        except Exception:
            pg = 1
        q = urllib.parse.quote(str(key))
        body = self._get("/index.php/vod/search.html?wd={q}".replace("{q}", q))
        vods = self._cards(body)
        if not vods:
            # degrade to latest so search never shows an empty screen
            body = self._get(BASE + "/index.php/vod/type/id/1/page/%d.html" % max(1, pg))
            vods = self._cards(body)
        return {"list": vods, "page": pg, "pagecount": 999,
                "limit": len(vods), "total": 99999}
